// ====== CONFIG ======
const ONLY_LAST_HOURS = 24;

// Keyword "Positive" (Must match at least one)
const INCLUDE_REGEX = [
  /\bai\b/i,
  /\bartificial intelligence\b/i,
  /\btech\b/i,
  /\bllm\b/i,
  /\bchatgpt\b/i,
  /\bgemini\b/i,
  /\bopenai\b/i,
  /\bautomation\b/i,
  /\brobotics\b/i,
  /\bmachine learning\b/i,
];

// Keyword "Negative" (If matched, exclude item)
const EXCLUDE_REGEX = [
  /\bcrypto\b/i,
  /\bbitcoin\b/i,
  /\bcoin\b/i,
  /\binvestment\b/i,
  /\bprice prediction\b/i,
  /\bxrp\b/i,
  /\bgiveaway\b/i,
  /\blive stream\b/i, // Often low quality or just looping music
];

// ======================================

const now = new Date();
const cutoff = new Date(now.getTime() - ONLY_LAST_HOURS * 60 * 60 * 1000);

function pickThumb(snippet) {
  return (
    snippet?.thumbnails?.high?.url ||
    snippet?.thumbnails?.medium?.url ||
    snippet?.thumbnails?.default?.url ||
    ''
  );
}

function matchAny(regexList, text) {
  return regexList.some((re) => re.test(text));
}

const out = [];

for (const item of $input.all()) {
  const j = item.json;

  const videoId = j?.id?.videoId || '';
  const snippet = j?.snippet || {};

  const title = snippet?.title || '';
  const description = snippet?.description || '';
  const channelTitle = snippet?.channelTitle || '';
  const publishedAt = snippet?.publishedAt || snippet?.publishTime || '';

  if (!videoId || !title) continue;

  // Time filter (if publishedAt parse is possible)
  if (publishedAt) {
    const d = new Date(publishedAt);
    if (!Number.isNaN(d.getTime()) && d < cutoff) continue;
  }

  // Content filter
  const haystack = `${title}\n${description}\n${channelTitle}`;
  if (!matchAny(INCLUDE_REGEX, haystack)) continue;
  if (matchAny(EXCLUDE_REGEX, haystack)) continue;

  out.push({
    json: {
      title,
      link: `https://www.youtube.com/watch?v=${videoId}`,
      description,
      source: `YouTube - ${channelTitle || 'Unknown'}`,
      publishedAt,
      thumbnail: pickThumb(snippet),
      channelTitle,
      videoId,
    }
  });
}

return out;

// ===== CONFIG =====
const MAX_ITEMS = 10000; // high limit = get all

// ==================

function cleanText(str) {
  return String(str || '')
    .replace(/<[^>]*>/g, ' ')     // remove HTML
    .replace(/&#\d+;/g, ' ')      // remove encoded chars
    .replace(/\s+/g, ' ')
    .trim();
}

function parseDate(v) {
  const d = new Date(v);
  return isNaN(d.getTime()) ? null : d.toISOString();
}

// ===== MAIN =====
const seen = new Set();
const articles = [];

for (const item of $input.all()) {
  const j = item.json || {};

  // ❌ skip error objects
  if (j.error) continue;

  const title = cleanText(j.title);
  const link = (j.link || '').split('?')[0]; // remove tracking params
  const description = cleanText(j.contentSnippet || j.description || '');
  const publishedAt = parseDate(j.isoDate || j.pubDate || j.date);

  if (!title || !link) continue;

  // 🔁 remove duplicates
  if (seen.has(link)) continue;
  seen.add(link);

  // 🌍 detect source
  let source = "Unknown";
  if (link.includes("bbc.com")) source = "BBC";
  else if (link.includes("theverge.com")) source = "The Verge";
  else if (link.includes("nytimes.com")) source = "NYTimes";
  else if (link.includes("reuters.com")) source = "Reuters";

  articles.push({
    title,
    description,
    link,
    source,
    publishedAt
  });
}

// 🕒 sort latest first
articles.sort((a, b) => new Date(b.publishedAt) - new Date(a.publishedAt));

// ===== OUTPUT =====
return [{
  json: {
    total: articles.length,
    articles: articles.slice(0, MAX_ITEMS)
  }
}];

const item = $input.first().json;

// ✅ build newsContext from articles if not present
let raw = item.newsContext;

if (!raw && Array.isArray(item.articles)) {
  raw = item.articles
    .map(a => `${a.title} (${a.link})`)
    .join('\n');
}

// ❌ still invalid
if (!raw || typeof raw !== "string") {
  throw new Error("newsContext must be a string");
}

// ===== PROCESS =====

// 1) Extract URLs
const urlRegex = /(https?:\/\/[^\s)]+)/g;

// 2) Split lines
const lines = raw.split('\n').map(l => l.trim()).filter(Boolean);

// 3) Build structured news
let news = []; // ✅ IMPORTANT (fix for your error)

for (let line of lines) {
  const urls = line.match(urlRegex);

  if (urls) {
    let title = line.replace(urlRegex, '').trim();

    title = title
      .replace(/\[.*?\]/, '')
      .replace(/:\s*$/, '')
      .trim();

    if (title.length > 80) {
      title = title.slice(0, 77) + '...';
    }

    news.push({
      title,
      url: urls[0]
    });
  }
}

// ===== SEND ALL (with Telegram limit fix) =====

const MAX_LENGTH = 4000;
let messages = [];

let currentMessage = `<b>Morning Briefing</b>\n\n`;

for (const n of news) {
  const line = `• <a href="${n.url}">${n.title}</a>\n`;

  if ((currentMessage + line).length > MAX_LENGTH) {
    messages.push(currentMessage);
    currentMessage = '';
  }

  currentMessage += line;
}

if (currentMessage) {
  messages.push(currentMessage);
}

// Title
const today = new Date().toISOString().split('T')[0];
const title = `${today} Morning Briefing`;

// ✅ return multiple messages
return messages.map(msg => ({
  json: {
    title,
    telegram_body: msg
  }
}));
